predicted_sql:
WITH mount_hope_point AS (
  SELECT ST_SetSRID(ST_MakePoint(-76.429747, 40.227758), 4326)::geography AS geom
)
SELECT 
  (ST_Value(r.rast, ST_Transform(mh.geom, 4326)::geometry)) > 220 AS is_elevation_greater_than_220
FROM 
  public.dem_us r,
  mount_hope_point mh
WHERE 
  ST_Intersects(r.rast, ST_Transform(mh.geom, 4326)::geometry);

